import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # --- summarize history cheaply ---
    opp_c = 0
    own_d = 0
    cc = cd = dc = dd = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        if me == 'D':
            own_d += 1
        if me == 'C':
            if op == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    # --- opening: cooperate, then calibrated retaliation ---
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'
    if n < 5:
        # punish a defection promptly, but don't spiral
        if opp_d >= 2:
            return 'D'
        return 'C'

    # --- late game: exploit reliably cooperative opponents ---
    if n >= 96:
        coop_rate = opp_c / float(n)
        if coop_rate > 0.75:
            return 'D'
        if coop_rate < 0.35:
            return 'D'
        return 'C' if last_opp == 'C' else 'D'

    # --- identify highly cooperative opponents ---
    coop_rate = opp_c / float(n)

    # Count recent opponent defections over last few windows
    recent5 = history[-5:]
    opp_def5 = 0
    for _, op in recent5:
        if op == 'D':
            opp_def5 += 1

    recent10 = history[-10:]
    opp_def10 = 0
    for _, op in recent10:
        if op == 'D':
            opp_def10 += 1

    # Count trailing streak of opponent defections
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    # Count trailing streak of opponent cooperation
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_c += 1
        else:
            break

    # --- exploit safe cooperators somewhat, but mostly keep peace ---
    if coop_rate >= 0.9:
        # Almost always cooperate; take occasional free shots,
        # but avoid triggering retaliation spirals.
        if last_opp == 'D' and opp_def5 >= 2:
            return 'D'
        if n < 90 and opp_d <= 1 and last_opp == 'C':
            # rare probing only if opponent forgave our earlier defections
            if own_d > 0 and last_me == 'C' and rng.random() < 0.06:
                return 'D'
        return 'C'

    # --- handle sustained defectors: stop feeding them ---
    if opp_d >= 4 and opp_def10 >= 5:
        if last_opp == 'D' or opp_def5 >= 2:
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    if streak_d >= 3:
        # Against persistent defection, defect but test once rarely
        if n < 95 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # --- moderate regime: forgiving tit-for-tat with early retaliation ---
    if last_opp == 'D':
        # Opponent just defected.
        if streak_d >= 2:
            return 'D'
        # If they're usually cooperative, punish once then return.
        if coop_rate >= 0.6:
            if last_me == 'D':
                # already punished; try returning to cooperation
                return 'C'
            return 'D'
        # Otherwise mirror defection with some probability
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # last_opp == 'C'
    if streak_c >= 4:
        # Long mutual cooperation: keep it going, avoid selfish probes that cause wars
        if last_me == 'D' and rng.random() < 0.5:
            return 'C'
        return 'C'

    if opp_def10 >= 3:
        # Opponent cooperated now but has been shaky; be wary
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    return 'C'
